{
	assert.ok(row.includes("Ordinary source: Node JavaScript / TypeScript: Installed checks passed (input, result, field)"));
	assert.ok(row.includes("Reviewed IR: Node JavaScript / TypeScript: Installed checks passed (input, result, field)"));
	assert.ok(row.includes("Browser / React / Worker: Installed checks passed (input, result)"));
}
else
{
	assert.ok(row.includes("Ordinary source: Installed checks passed (input, result)"), path);
	assert.ok(row.includes("Reviewed IR: Installed checks passed (input, result)"), path);
}

const allInstalled = cells.filter(cell => cell.stages.installedExecution.state === "passed");
const fields = allInstalled.filter(cell => cell.position === "field");
assert.deepEqual(fields.map(cell => cell.id).sort(), nominalSubtypeNpmProfiles.flatMap(profile => ["ordinary-source", "reviewed-ir"].map(path => `${profile}/subtype/${path}/field`)).sort());
for(const cell of fields) for(const stage of Object.values(cell.stages))
	assert.deepEqual(stage.evidence, ["full", "result-only"].map(mode => `nominal-subtype-npm-${cell.path === "ordinary-source" ? "ordinary" : "reviewed"}-${mode}-installed`));
const installed = allInstalled.filter(cell => ["parameter", "result"].includes(cell.position));
assert.equal(allInstalled.length, installed.length + 4);

const nominal = nominalSubtypeNpmProfiles.includes(cell.profile)
	? ["full", "result-only"].map(mode => `nominal-subtype-npm-${cell.path === "ordinary-source" ? "ordinary" : "reviewed"}-${mode}-installed`) : [];
if(nominal.length)
{
	assert.ok(cell.hostType.endsWith(nominalSubtypeNpmHostSuffix));
	cell = { ...cell, hostType: cell.hostType.slice(0, -nominalSubtypeNpmHostSuffix.length) };
}
